-- Spec 0050 parity fixture: structure of the tables analytics-service reads but does not own.
-- Dumped with no data from ticketing_system_test (ticket-service migrations) on 2026-11-26.
-- Foreign keys and AUTO_INCREMENT counters are stripped: analytics only reads these tables, and the
-- fixture must load without the tables they point at (SLA policies, ticket types, and so on).
-- Refresh this file whenever a ticket-service migration changes one of these tables.
-- Loaded by analytics-service tests/RefreshReportingDatabase.php before analytics' own migrations.
CREATE TABLE `tickets` (
  `ticket_ID` bigint unsigned NOT NULL AUTO_INCREMENT,
  `ticket_number` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `machine_ID` bigint unsigned DEFAULT NULL,
  `equipment_name` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `problem_category_ID` bigint unsigned DEFAULT NULL,
  `created_by` bigint unsigned NOT NULL,
  `assigned_to` bigint unsigned DEFAULT NULL,
  `ticket_type_ID` bigint unsigned NOT NULL,
  `is_internal` tinyint(1) NOT NULL DEFAULT '0',
  `origin` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'manual',
  `priority_ID` bigint unsigned DEFAULT NULL,
  `ticket_status_ID` bigint unsigned NOT NULL,
  `held_from_status_ID` bigint unsigned DEFAULT NULL,
  `hold_reason` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `escalation_reason` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `in_progress_owner` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `previous_in_progress_owner` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `proof_rejected` tinyint(1) NOT NULL DEFAULT '0',
  `rejection_reason` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `sla_ID` bigint unsigned DEFAULT NULL,
  `sla_rule_id` bigint unsigned DEFAULT NULL,
  `response_due_at` datetime DEFAULT NULL,
  `resolution_due_at` datetime DEFAULT NULL,
  `last_reminder_sent_at` datetime DEFAULT NULL,
  `sla_status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'On Track',
  `sla_started_at` datetime DEFAULT NULL,
  `sla_paused_at` datetime DEFAULT NULL,
  `sla_paused_total_seconds` int unsigned NOT NULL DEFAULT '0',
  `first_response_at` datetime DEFAULT NULL,
  `response_sla_status` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `resolution_sla_status` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `resolved_at` datetime DEFAULT NULL,
  `closed_at` datetime DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `requested_by` bigint unsigned DEFAULT NULL,
  `branch_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `branch_priority_override_id` bigint unsigned DEFAULT NULL,
  `branch_sla_policy_id` bigint unsigned DEFAULT NULL,
  `department_id` bigint unsigned DEFAULT NULL,
  `sla_risk_notified_at` datetime DEFAULT NULL,
  `sla_breach_notified_at` datetime DEFAULT NULL,
  `last_sla_breach_alert_at` datetime DEFAULT NULL,
  `first_cs_response_at` datetime DEFAULT NULL,
  PRIMARY KEY (`ticket_ID`),
  UNIQUE KEY `tickets_ticket_number_unique` (`ticket_number`),
  KEY `tickets_machine_id_foreign` (`machine_ID`),
  KEY `tickets_problem_category_id_foreign` (`problem_category_ID`),
  KEY `tickets_ticket_type_id_foreign` (`ticket_type_ID`),
  KEY `tickets_priority_id_foreign` (`priority_ID`),
  KEY `tickets_ticket_status_id_foreign` (`ticket_status_ID`),
  KEY `tickets_sla_id_foreign` (`sla_ID`),
  KEY `idx_tickets_created_by_created_at` (`created_by`,`created_at`),
  KEY `idx_tickets_assigned_to_created_at` (`assigned_to`,`created_at`),
  KEY `idx_tickets_created_at` (`created_at`),
  KEY `idx_tickets_is_internal_created_at` (`is_internal`,`created_at`),
  KEY `idx_tickets_requested_by_created_at` (`requested_by`,`created_at`),
  KEY `tickets_sla_rule_id_foreign` (`sla_rule_id`),
  KEY `idx_tickets_customer_open_limit` (`created_by`,`is_internal`,`ticket_status_ID`,`closed_at`,`resolved_at`),
  KEY `idx_tickets_requester_open_limit` (`requested_by`,`is_internal`,`ticket_status_ID`,`closed_at`,`resolved_at`),
  KEY `tickets_in_progress_owner_index` (`in_progress_owner`),
  KEY `tickets_branch_priority_override_id_index` (`branch_priority_override_id`),
  KEY `idx_tickets_resolution_due_at` (`resolution_due_at`),
  KEY `tickets_sla_status_index` (`sla_status`),
  KEY `idx_tickets_branch_created_at` (`branch_id`,`created_at`),
  KEY `idx_tickets_branch_status` (`branch_id`,`ticket_status_ID`),
  KEY `idx_tickets_assigned_status` (`assigned_to`,`ticket_status_ID`),
  KEY `idx_tickets_created_by_status` (`created_by`,`ticket_status_ID`),
  KEY `idx_tickets_requested_by_status` (`requested_by`,`ticket_status_ID`),
  KEY `tickets_branch_sla_policy_id_index` (`branch_sla_policy_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `ticket_statuses` (
  `ticket_status_ID` bigint unsigned NOT NULL AUTO_INCREMENT,
  `status_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `color_code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`ticket_status_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `ticket_priorities` (
  `priority_ID` bigint unsigned NOT NULL AUTO_INCREMENT,
  `priority_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `color_code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`priority_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `ticket_assignments` (
  `assignment_ID` bigint unsigned NOT NULL AUTO_INCREMENT,
  `ticket_ID` bigint unsigned NOT NULL,
  `employee_ID` bigint unsigned NOT NULL,
  `assigned_by` bigint unsigned NOT NULL,
  `assignment_status` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'assigned',
  `assigned_at` datetime DEFAULT NULL,
  `accepted_at` datetime DEFAULT NULL,
  `completed_at` datetime DEFAULT NULL,
  `last_reminder_sent_at` datetime DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`assignment_ID`),
  KEY `ticket_assignments_ticket_id_foreign` (`ticket_ID`),
  KEY `ticket_assignments_employee_id_foreign` (`employee_ID`),
  KEY `ticket_assignments_assigned_by_foreign` (`assigned_by`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `ticket_assignment_periods` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `ticket_ID` bigint unsigned NOT NULL,
  `employee_ID` bigint unsigned NOT NULL,
  `assigned_by` bigint unsigned DEFAULT NULL,
  `assigned_at` timestamp NOT NULL,
  `ack_due_at` timestamp NULL DEFAULT NULL,
  `accepted_at` timestamp NULL DEFAULT NULL,
  `paused_at` timestamp NULL DEFAULT NULL,
  `paused_seconds` int unsigned NOT NULL DEFAULT '0',
  `ack_paused_seconds` int unsigned NOT NULL DEFAULT '0',
  `released_at` timestamp NULL DEFAULT NULL,
  `release_reason` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `ticket_assignment_periods_assigned_by_foreign` (`assigned_by`),
  KEY `tap_employee_assigned_idx` (`employee_ID`,`assigned_at`),
  KEY `tap_ticket_released_idx` (`ticket_ID`,`released_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `reassignment_requests` (
  `request_id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `ticket_id` bigint unsigned NOT NULL,
  `employee_id` bigint unsigned NOT NULL,
  `reason` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `deny_reason` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `status` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  `requested_at` timestamp NULL DEFAULT NULL,
  `reviewed_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`request_id`),
  KEY `reassignment_requests_ticket_id_index` (`ticket_id`),
  KEY `reassignment_requests_employee_id_index` (`employee_id`),
  KEY `reassignment_requests_status_index` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `employees` (
  `emp_id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `email` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `password_hash` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `first_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `last_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `role` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'service',
  `department` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `branch` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `branch_id` bigint unsigned DEFAULT NULL,
  `phone_number` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `position_level` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `technical_role` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `is_ticketing_employee` tinyint(1) NOT NULL DEFAULT '0',
  `failed_login_count` int unsigned NOT NULL DEFAULT '0',
  `locked_until` timestamp NULL DEFAULT NULL,
  `last_login_at` timestamp NULL DEFAULT NULL,
  `last_seen_at` timestamp NULL DEFAULT NULL,
  `password_change_at` timestamp NULL DEFAULT NULL,
  `last_synced_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`emp_id`),
  UNIQUE KEY `employees_email_unique` (`email`),
  KEY `employees_branch_index` (`branch`),
  KEY `employees_branch_id_index` (`branch_id`),
  KEY `employees_position_level_index` (`position_level`),
  KEY `employees_technical_role_index` (`technical_role`),
  KEY `employees_is_active_index` (`is_active`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `branches` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `slug` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `code` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `region` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `address` text COLLATE utf8mb4_unicode_ci,
  PRIMARY KEY (`id`),
  UNIQUE KEY `branches_slug_unique` (`slug`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `machines` (
  `machine_ID` bigint unsigned NOT NULL AUTO_INCREMENT,
  `equipment_uid` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `category_ID` bigint unsigned NOT NULL,
  `client_ID` bigint unsigned NOT NULL,
  `asset_type` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'equipment',
  `cms_customer_uid` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `contract_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `contract_end_date` date DEFAULT NULL,
  `cms_contract_active` tinyint(1) DEFAULT NULL,
  `branch_id` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `machine_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `serial_number` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `model` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `brand` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `status` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `purchase_date` datetime DEFAULT NULL,
  `last_maintenance_date` datetime DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`machine_ID`),
  UNIQUE KEY `machines_serial_number_unique` (`serial_number`),
  UNIQUE KEY `machines_equipment_uid_unique` (`equipment_uid`),
  KEY `machines_category_id_foreign` (`category_ID`),
  KEY `machines_client_id_foreign` (`client_ID`),
  KEY `machines_branch_id_index` (`branch_id`),
  KEY `machines_cms_customer_uid_index` (`cms_customer_uid`),
  KEY `machines_client_asset_type_index` (`client_ID`,`asset_type`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `problem_categories` (
  `problem_category_ID` bigint unsigned NOT NULL AUTO_INCREMENT,
  `category_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `branch_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
